log.source:
// Sun-tracking solar panel: a single-axis tracker that swings east to west with the
// local solar hour and reports its output. Two shapes: a post and a 2 x 1 m panel.
//
// Facts read at run time:
//   FACT_MARS_SOLAR_CONSTANT_MEAN                  sunlight above the air, mean distance [mars.solar.constant_mean]
//   FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36 clear-season dust optical depth [jezero.dust.optical_depth_background_my36]
// Player's assumptions (not facts):
//   - panel area 2 m2, efficiency 25 %
//   - dust dims only the direct beam, as exp(-tau / cos(zenith)); scattered skylight is ignored
//   - sun path as at an equator at equinox: rises at hour 6, overhead at 12, sets at 18
//     (Jezero's latitude and the season are ignored; the world clock has no season)
//   - stowed flat at night
// The 15 degrees per hour is only the geometry of a 24-hour clock, not a Mars number.
import { read, fact, spawn, pose, state_set, log, ENV_LOCAL_HOUR, SHAPE_CYLINDER, SHAPE_PANEL,
         FACT_MARS_SOLAR_CONSTANT_MEAN, FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36 } from "./host";

const AREA_M2: f32 = 2.0;          // player's assumption
const EFFICIENCY: f32 = 0.25;      // player's assumption
const HALF_PI: f32 = 1.5707963;
const RAD_PER_HOUR: f32 = 0.2617994; // 2*pi / 24: clock geometry

const SLOT_WATTS: i32 = 0;
const SLOT_FLUX: i32 = 1;
const SLOT_ANGLE: i32 = 2;
const SLOT_SUN_UP: i32 = 3;

const LOG_HOURLY_W: i32 = 10;      // value: electrical output (W) at the start of each local hour
const LOG_S0: i32 = 11;            // value: sunlight above the air read from the fact index (W/m^2)
const LOG_TAU: i32 = 12;           // value: dust optical depth read from the fact index

let post: i32 = -1;
let panel: i32 = -1;
let s0: f32 = 0.0;                 // W/m^2 above the atmosphere
let tau: f32 = 0.0;                // dust optical depth
let lastHour: i32 = -1;

export function init(): void {
  post = spawn(SHAPE_CYLINDER, 0.1, 1.2, 0.1, 0.7, 0.7, 0.7);
  panel = spawn(SHAPE_PANEL, 2.0, 1.0, 0.04, 0.1, 0.15, 0.45); // 2 m2, the player's area
  pose(post, 0.0, 0.6, 0.0, 0.0, 0.0);
  s0 = fact(FACT_MARS_SOLAR_CONSTANT_MEAN);
  tau = fact(FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36);
  if (!isFinite(s0)) s0 = 0.0;
  if (!isFinite(tau)) tau = 0.0;
  log(LOG_S0, s0);
  log(LOG_TAU, tau);
}

export function tick(dt: f32): void {
  const hour = read(ENV_LOCAL_HOUR);
  const h: f32 = (hour - 12.0) * RAD_PER_HOUR;   // hour angle: 0 at noon, - morning, + afternoon

  let flux: f32 = 0.0;
  let tilt: f32 = -HALF_PI;                      // stowed flat, face up
  let sunUp: f32 = 0.0;
  const cosZenith = Mathf.cos(h);                // equator-at-equinox sun path (player's assumption)
  if (h > -HALF_PI && h < HALF_PI && cosZenith > 0.0) {
    sunUp = 1.0;
    // the tracker keeps the panel square to the sun, so all direct light lands on it;
    // dust removes exp(-tau / cos(zenith)) of the beam (player's assumption)
    flux = s0 * Mathf.exp(-tau / cosZenith);
    tilt = h - HALF_PI;                          // swings from one horizon through flat to the other
  }
  const watts: f32 = flux * AREA_M2 * EFFICIENCY;

  // yaw a quarter turn so the hinge runs along the object's forward axis, then tilt about it
  pose(panel, 0.0, 1.3, 0.0, HALF_PI, tilt);

  state_set(SLOT_WATTS, watts);
  state_set(SLOT_FLUX, flux);
  state_set(SLOT_ANGLE, sunUp > 0.0 ? h : 0.0);
  state_set(SLOT_SUN_UP, sunUp);

  const hr = <i32>Mathf.floor(hour);
  if (hr != lastHour) {
    lastHour = hr;
    log(LOG_HOURLY_W, watts);
  }
}

